import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherDashboard({ userName, userId, handleLogout }) {
  const [assignedSubjects, setAssignedSubjects] = useState([]);
  const [activeMenu, setActiveMenu] = useState('Dashboard');

  // 🌐 Database එකෙන් මේ ගුරුවරයාට විතරක් අදාළ පන්ති ඇදලා ගැනීම
  useEffect(() => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => {
        // ලොග් වුණු ගුරුවරයාගේ නම ටයිම්ටේබල් එකේ teacher කෝලම් එකේ තියෙනවාද කියලා බලනවා
        const myClasses = res.data.filter(item => item.teacher.toLowerCase().includes(userName.toLowerCase()));
        setAssignedSubjects(myClasses);
      })
      .catch(err => console.error("Error fetching teacher classes:", err));
  }, [userName]);

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 AURA PEN GREEN SIDEBAR */}
      <div style={{ width: '260px', backgroundColor: '#15803d', color: '#fff', display: 'flex', flexDirection: 'column', padding: '20px 0', boxShadow: '4px 0 10px rgba(0,0,0,0.05)' }}>
        <div style={{ padding: '0 20px 20px 20px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '20px' }}>
          <h2 style={{ margin: 0, color: '#fff', fontSize: '22px', fontWeight: '800' }}>AURA PEN</h2>
          <span style={{ fontSize: '11px', color: '#dcfce7', opacity: 0.9, fontWeight: '600' }}>TEACHER PORTAL</span>
        </div>

        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '5px' }}>
          {[
            { id: 'Dashboard', label: '📊 Dashboard' },
            { id: 'My Subjects', label: '📚 My Subjects' },
            { id: 'Manage Quizzes', label: '📝 Manage Quizzes' },
            { id: 'Quiz Reports', label: '📈 Quiz Reports' },
            { id: 'Discussion Forum', label: '💬 Discussion Forum' },
            { id: 'Feedback', label: '⭐ Feedback' },
            { id: 'My Profile', label: '👤 My Profile' }
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveMenu(item.id)}
              style={{
                width: '100%', padding: '14px 20px', border: 'none',
                backgroundColor: activeMenu === item.id ? '#166534' : 'transparent',
                color: '#fff', fontSize: '14px', fontWeight: '600', cursor: 'pointer',
                textAlign: 'left', transition: '0.2s', borderLeft: activeMenu === item.id ? '5px solid #38bdf8' : '5px solid transparent'
              }}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div style={{ padding: '20px' }}>
          <button onClick={handleLogout} style={{ width: '100%', backgroundColor: 'transparent', border: '1px solid #fff', color: '#fff', padding: '10px', borderRadius: '6px', fontWeight: '700', cursor: 'pointer' }}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* ⚪ MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '35px', overflowY: 'auto' }}>
        
        {/* Welcome Banner */}
        <div style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', borderLeft: '6px solid #15803d', marginBottom: '30px', border: '1px solid #e2e8f0', borderLeftWidth: '6px' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', fontWeight: '700' }}>👑 Welcome Back, Teacher ({userName})</h2>
          <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '14px' }}>Manage your academic activities, quizzes, and learning materials efficiently.</p>
        </div>

        {/* 📊 Analytics Cards 2 */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '25px', marginBottom: '35px' }}>
          
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', display: 'flex', alignItems: 'center', gap: '20px', border: '1px solid #e2e8f0' }}>
            <div style={{ backgroundColor: '#dcfce7', color: '#15803d', width: '60px', height: '60px', borderRadius: '12px', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '26px' }}>📚</div>
            <div>
              <h2 style={{ margin: 0, color: '#1e293b', fontSize: '28px', fontWeight: '800' }}>{assignedSubjects.length}</h2>
              <p style={{ margin: 0, color: '#64748b', fontSize: '14px', fontWeight: '600' }}>My Assigned Subjects</p>
            </div>
          </div>

          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', display: 'flex', alignItems: 'center', gap: '20px', border: '1px solid #e2e8f0' }}>
            <div style={{ backgroundColor: '#fef3c7', color: '#b45309', width: '60px', height: '60px', borderRadius: '12px', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '26px' }}>📝</div>
            <div>
              <h2 style={{ margin: 0, color: '#1e293b', fontSize: '28px', fontWeight: '800' }}>0</h2>
              <p style={{ margin: 0, color: '#64748b', fontSize: '14px', fontWeight: '600' }}>Total Active Quizzes</p>
            </div>
          </div>

        </div>

        {/* 📅 Table Section */}
        <div style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
          <h3 style={{ margin: '0 0 20px 0', color: '#15803d', fontSize: '18px', fontWeight: '700' }}>📚 My Assigned Subjects</h3>
          
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px', backgroundColor: '#fafafa' }}>
                <th style={{ padding: '15px' }}>Course/Grade</th>
                <th style={{ padding: '15px' }}>Subject Code</th>
                <th style={{ padding: '15px' }}>Subject Name</th>
                <th style={{ padding: '15px', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {assignedSubjects.length > 0 ? (
                assignedSubjects.map((sub, i) => (
                  <tr key={i} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px', color: '#334155' }}>
                    <td style={{ padding: '16px 15px', fontWeight: '600' }}>{sub.grade}</td>
                    <td style={{ padding: '16px 15px' }}>
                      <code style={{ backgroundColor: '#e0f2fe', padding: '4px 8px', borderRadius: '4px', color: '#0369a1', fontWeight: '600' }}>
                        {sub.subject.toUpperCase().substring(0, 3)}_{sub.id}
                      </code>
                    </td>
                    <td style={{ padding: '16px 15px', fontWeight: '500' }}>{sub.subject}</td>
                    <td style={{ padding: '16px 15px', textAlign: 'center' }}>
                      <button style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: '6px', fontSize: '13px', cursor: 'pointer', fontWeight: '600' }}>
                        📁 Manage
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8' }}>
                    No assigned classes found for this Teacher name in the Timetable.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
}
